cards=[]
cards.append(compact('chen_yuelan','陈月兰','陈月兰是川西督军陈天豪的长女，也是白素和白奇伟的母亲。她受过新式教育，性格独立，不肯只按父亲安排生活，又从独目天王学得高明武艺，能够在别人未能攀援的高墙与山野中来去。她与白老大相识同行，进入苗疆共同生活，本已有幼子并再次怀孕，却在看见铁头娘子对白老大的亲近后认定丈夫变心。她不等解释便离开，后来把新生女儿送回，自己仍不相见，长年的怨恨由此与亲情纠缠。留在深山时，她曾传授一名当地少年武艺，有灵猴抬乘相随；这不是她成为外星人的证据。二十多年后，她得知父亲死于旧部叛变，出山亲手杀死两个首恶，在重庆遇到并感谢云一风。谈到已有外孙女时，她既悲苦又有怨意。此后红绫失踪，后来的居所、儿歌与记忆碎片使卫白确认孩子是被外婆抱走抚育，直到她又不知所终，孩子才由灵猴带大。她是否接受异星人的脑改造并离开地球，仍属推测，不能写成已经拥有异星全能力。综合卡保存她的才气、果决、复仇与对家人的伤害，也给终局知识留下反思误会的可能，不把她简化成专为解释女儿身世而存在的幽灵。','最后确认曾在深山抚育红绫后失踪；接受异星改造并远行的说法未证实，采用最后明确的人类武者形态',['主角','阶段性对立者'],'维护自身情感尊严、追索家仇与亲情，同时面对自己决绝造成的分离','文雅而有主见，少解释内心，一旦决定便立即行动','对背叛高度敏感，可用隐居、决裂或致命复仇回应；不默认她已知道所有真相','力量和决心不能保证判断正确，终局演绎允许她核实误会而不强迫立即原谅',[ab('高明武术和潜行','师承独目天王，能壁虎游墙、潜入戒备住所、使兵刃完成复仇','肉身仍受伤害，无证据可无限攀无摩擦表面或规避所有枪械'),ab('灵猴协作与授艺','在特定群体中受到灵猴协助，并教授人类弟子防身本领','依关系和具体猴群，不是控制一切动物；异星脑技术未证实为本人所有')],[ev('087',715,846,'弟子回忆、时间和灵猴随行'),ev('087',2782,2849,'夫妻离散原因及误会分析'),ev('087',2937,3038,'复仇、云一风证词与外孙女'),ev('087',3177,3211,'儿歌、居所和失踪线索'),ev('089',2801,2844,'异星脑改造仍是假说')],profile='martial',aliases=['陈大小姐','白夫人']))
cards.append(compact('chen_yuemei','陈月梅（韩夫人）','陈月梅是陈天豪的小女儿，幼时收到姐姐陈月兰托人送来的特殊虫物，在父亲膝头天真发问，尚不知道这个生日礼会连接一生的命运。帅府兵变时，父亲临终把她交给独目天王，后来她嫁入富裕韩家，丈夫韩三早亡。成年后的她清丽温柔，仍执着寻找记忆已模糊的姐姐，带着何先达与珍贵礼物拜访卫斯理，希望取得与蛊苗联系的途径。被拒绝后，她没有就此放弃，携一愿神虫深入苗疆。同行的何先达在酒后对她实施性暴力，她逃离，不愿再与施害者相见，独自在艰险山地中生存，后来产下蓝丝。猛哥偶然听见她的呻吟，救下逆产婴儿，她却已无法获救。她最后牵挂的是孩子的生命，身上的虫物又使猛哥明白这不是可以置之不理的陌生母女。卡片不采用叙述者把惨剧归因于女子刚烈的判断来替施害者减责，也不把她的离开写成错误的拒绝宽恕。她没有继承姐姐的高深武功，贵重信物只提供有限社会请求资格，不是随意实现愿望的宇宙法则。演绎中，她可以求援、坚持寻找亲人和选择与谁保持距离，拥有超出受害标签的记忆与意愿。','苗疆产下蓝丝后死亡；恢复最后能够自主行动的人类形态并保留女儿获救的终局认知','主角','寻找失散的姐姐、维护身体和情感自主、保护孩子','礼貌而坚定地提出请求，愿以实际行动寻找亲人','遇拒绝可继续寻找其他途径；遭侵害后优先离开危险关系，保留是否相见的决定','亲属、主仆和感恩关系都不赋予他人侵犯自己的权利',[ab('求助与关系交涉','利用所知家世、信物和资源寻求护送、引介与族群帮助','信物作用依对方识别和习俗，不是许愿术；没有高明战斗或独立治疗能力')],[ev('086',2018,2185,'身份、寻姊和求助'),ev('086',2190,2256,'一愿神虫与父女往事'),ev('087',548,608,'父亲托孤与婚后经历'),ev('089',2250,2379,'产女、获救婴儿与母亲死亡'),ev('089',2895,2954,'何的忏悔证实侵害与女儿得知身世')],profile='ordinary',aliases=['陈二小姐','韩夫人']))
c=compact('he_xianda','何先达','何先达曾是韩家三堂主的随从，外貌堂堂、谈吐有礼，陪同丧夫的陈月梅寻找姐姐时，对她十分恭敬，也能说明贵重器物和江湖礼数。进入苗疆后，他却在饮酒后对她实施性暴力，醒来时人已离去。他寻找无果，误以为她已经死在山中，自觉罪重，二十余年不离苗疆，在树皮上反复写下忏悔，守着象征她的雕像。他不知道她在十个月后生下自己的女儿蓝丝才死，痛悔也不能代替受害者的原谅。蓝丝后来读到记录，选择把母女故事传唱出去，让他自己听见，父女终于有了相认与共同生活的可能。后来的祸根事件中，他已能与卫白同行，带铁天音回蓝家峒，在其发作时迅速控制身体、防止伤害，用金创药处理兽爪伤，并愿尝试以内家功夫缓解其脑部问题；最终是否治愈没有确定结果。卡片保留这位武术强者从谦恭表象到严重侵害、长期悔恨再到具体照护的复杂过程，不因他武功高或救过别人便抹去责任。他也不应不断背诵忏悔词，而要在新情境中以尊重界限、停止替别人决定的行动面对过去。','已与蓝丝相认并参与蓝家峒事件，尝试帮助铁天音；后者病情彻底治愈未获确认',['主角','阶段性对立者'],'承担无法抹去的伤害，珍惜女儿并在可做的事情上保护他人','言语克制，先听别人需要，熟悉江湖礼数和随护事务','遇人失控时以武术迅速制止伤害、处理伤口；不得以保护名义侵犯自主','悔恨与善举都不替代责任；对方可以拒绝接触，治疗只说已见结果',[ab('高深武术与擒制','动作迅捷，能从背后抱住挣扎的铁天音并承受踢击，擅长山野行动','人体仍受伤害；叙述者所说无人挣脱是夸张，不作跨世界绝对规则'),ab('金创药与内家调理','有伤药能使已见兽爪创口迅速收紧，以内家方法尝试帮助铁天音','药需在手，适用范围有限；脑部病症治愈未确认，不能复活或重建任意损伤')],[ev('086',2018,2117,'随护、谈吐与器物知识'),ev('089',2895,2958,'侵害、长期忏悔及女儿寻父办法'),ev('091',2730,2776,'带铁天音前来'),ev('091',2825,2868,'制止发作与伤药'),ev('091',3087,3088,'只承诺试治'),ev('091',3165,3165,'卫仅希望已治好')],profile='martial');rate(c,[5,1,1,5,2,8],neg=(2,1,1),tier='强',reason='高深近战及有限伤药和调理；不把希望治愈脑病作为已成普遍能力');cards.append(c)
cards.append(compact('paoge_shangshu','哥老会执掌尚书大爷','这名未留下本名的老人，年轻时在哥老会总坛内八堂排行第七，号执掌尚书。他的身份使他既在白老大独闯总坛的暴烈现场，也能出入陈天豪府邸，与其他头面人物讨论白老大和陈月兰的去向。当年的帮会既受白老大武力震动，又因为丢了脸面想把他截下，个人判断被集体荣辱裹挟；老人并不能以一个头衔就控制整场冲突。多年后卫斯理和白素循线找到他，才知道金贩在偏厅讲述沿江偶遇的经过。卫白请他见白老大叙旧，他却仍对当年的血战心存惧意，不愿会面，这份坦白显示旧日威势并没有随着岁月和礼貌邀请自动消散。后来他得知第四位堂主大麻子还活着，主动来信问二人是否愿见，促成又一次重要证词。他不是掌握全部白家秘密的幕后组织者，而是能把不同幸存者接起来的老江湖。卡片以老年联络与记忆为中心，职衔不兑换为法术，年轻时的帮会势力也不当作随身军团。演绎中他会掂量旧怨、面子和危险，再决定愿说到哪里；既可能犹豫，也能把自己害怕亲见的人介绍给愿意面对的人。','老年仍健在，通过来信促成大麻子与卫白会面；当前武功和旧组织控制力未证实','重要配角','保存江湖往事与人情联系，同时避开使自己畏惧的旧冲突','先听来意再联系合适的旧人，谈往事时注意面子和准确范围','被要求重见当年强敌时可明确拒绝，仍以信息方式帮助','曾在场不等于全知，帮会头衔不等于如今仍能发号施令',[ab('旧事证言与人脉引介','亲历总坛和帅府相关场面，后来联系仍健在的同僚','依记忆和对方愿意出现，不能召唤所有昔日帮众或确定未见后事')],[ev('086',2347,2405,'五名首领与金贩问话背景'),ev('087',982,1003,'尚书身份、拒见白老大及来信引介')],profile='expert'))
save(cards)
